        "components": "{name: Wofi, ref: 13rev-005, latitude: 8.7211666667, longitude: 38.5758888889}, {name: Kella, ref: 13rev-004, latitude: 8.7167777778, longitude: 38.6133333333}, {name: Simbiro, ref: 13rev-002, latitude: 8.7070833333, longitude: 38.5666666667}, {name: Balchit, ref: 13rev-003, latitude: 8.7591666667, longitude: 38.6194166667}, {name: Atebella, ref: 13rev-006, latitude: 8.7376944444, longitude: 38.5765277778}, {name: Gombore Garaba, ref: 13rev-001, latitude: 8.7034722222, longitude: 38.5990833333}",
